	  private double progresiviarketuar = 0.0;
        private double progresivipaguar = 0.0;
        private double gjendjamepare;
        private double totali = 0.0;
        private double gjendja = 0.0;


private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            {
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "1")
                {
                    e.Cancel = true;
                }
            }
}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            gjendja = progresiviarketuar - progresivipaguar + gjendjamepare;

            xrLabel21.Text = String.Format("{0:N2}", gjendja);
}

private void xrTableCell32_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
            {
                if (Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()) >= 0)
                {
                    xrTableCell32.Text = String.Format("{0:N2}", Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()));
                    gjendjamepare = Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString());
                }
                else
                {
                    xrTableCell32.Text = " ";
                }
            }
}

private void xrLabel8_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            progresiviarketuar = 0.0;
            progresivipaguar = 0.0;
}

private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

}

private void xrLabel36_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            totali = progresiviarketuar - progresivipaguar;
            if (totali >= 0)
            {
                xrLabel36.Text = String.Format("{0:N2}", totali);
            }
            else
            {
                xrLabel36.Text = " ";
            }
}

private void xrTableCell8_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
            {
                if (Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()) < 0)
                {
                    xrTableCell8.Text = String.Format("{0:N2}", Math.Abs(Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString())));
                    gjendjamepare = Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString());
                }
                else
                {
                    xrTableCell8.Text = " ";
                }
            }
}

private void xrLabel24_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            totali = progresiviarketuar - progresivipaguar;
            if (totali < 0)
            {
                xrLabel24.Text = String.Format("{0:N2}", Math.Abs(totali));
            }
            else
            {
                xrLabel24.Text = " ";
            }
}

private void xrLabel6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	string FilterAvancBanka = (string)report.Parameters["parameterFAB"].Value;
	string FilterAvancArka = (string)report.Parameters["parameterFAA"].Value;

            if (Convert.ToBoolean(GetCurrentColumnValue("LLOJARKABANKA")))
            {
                xrLabel6.Text = FilterAvancBanka + ":";
            }
            else
            {
                xrLabel6.Text = FilterAvancArka + ":";
            }
}

private void xrTableCell18_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
		var vleraarketueshme = Convert.ToDouble(GetCurrentColumnValue("vleraarketueshme"));
            var vlerapaguar = Convert.ToDouble(GetCurrentColumnValue("vlerapaguar"));
            if (vleraarketueshme >= 0)
            {
                xrTableCell18.Text = String.Format("{0:N2}", vleraarketueshme);
                xrTableCell25.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                {
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    {
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Arketim")
                        {
                            progresiviarketuar = progresiviarketuar + vleraarketueshme;
                        }
                    }
                }
            }
            if (vlerapaguar < 0)
            {
                xrTableCell18.Text = String.Format("{0:N2}", Math.Abs(vlerapaguar).ToString());
                xrTableCell25.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                {
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    {
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese")
                        {
                            progresiviarketuar = progresiviarketuar + Math.Abs(vlerapaguar);
                        }
                    }
                }
            }
}

private void xrTableCell25_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            var vleraarketueshme = Convert.ToDouble(GetCurrentColumnValue("vleraarketueshme"));
            var vlerapaguar = Convert.ToDouble(GetCurrentColumnValue("vlerapaguar"));
            if (vlerapaguar >= 0)
            {
                xrTableCell25.Text = String.Format("{0:N2}", vlerapaguar);
                xrTableCell18.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                {
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    {
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese")
                        {
                            progresivipaguar = progresivipaguar + vlerapaguar;
                        }
                    }
                }
            }
            if (vleraarketueshme < 0)
            {
                xrTableCell25.Text = String.Format("{0:N2}", Math.Abs(vleraarketueshme));
                xrTableCell18.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                {
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    {
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Arketim")
                        {
                            progresivipaguar = progresivipaguar + Math.Abs(vleraarketueshme);
                        }
                    }
                }
            }
}

