private void xrTableCell29_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (GetCurrentColumnValue("IDDOKUMENTI") != null)
            {
                xrTableCell29.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('ShtoVeprimBanka.aspx?scopeID="+scopeID+"&newScopeId=True&lloji=" + GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() + "&id=" + GetCurrentColumnValue("IDDOKUMENTI").ToString() + "&numer=" + GetCurrentColumnValue("NRDOKUMENTI").ToString() + "&shtim_modifikim=modifikim')";
                xrTableCell29.ForeColor = Color.SteelBlue;
                xrTableCell29.Target = "_self";
            }
}

